# ---------------------------------------------------------------------------

def _gen_config(rng):
    n_resources = rng.randint(1, 3)
    resources = {f"r{k}": rng.randint(1, 2) for k in range(n_resources)}
    names = sorted(resources)
    clients = ["A", "B", "C"]
